mapper.select:
select D.BOOKSET_ID as booksetId, D.BOOKSET_NAME as booksetName, A.FINPROD_ID as finprodId, C.FEE_TYPE as feeType,
A.PRIN as prin, DATE_FORMAT(A.VDATE, '%Y-%m-%d') as vdate, DATE_FORMAT(A.MDATE, '%Y-%m-%d') as mdate from FIN_TRADE_PRODUCT A inner join BOK_DETAIL_ID B on B.BUSI_ID = A.FINPROD_ID and B.TRADE_ID = A.FINPROD_ID inner join TRD_TRADE_FEE_DETAIL C on C.TRADE_ID = A.FINPROD_ID
and C.IS_PREPAID = 'Y' inner join BOK_BOOKSET D on D.BOOKSET_ID = B.BOOKSET_ID where A.FINPROD_TYPE = 'C19' AND D.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR} AND A.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

select D.FEE_TYPE as feeType, DATE_FORMAT(B.TRADE_DATE, '%Y-%m-%d') as tradeDate, IFNULL(E.PRIN,D.FEE_AMT) as prin from BOK_DEAL_ACCOUNTING A inner join TRD_PRODUCT_DEAL B on A.BUSI_NO = B.TRADE_ID and B.TRADE_STATUS != '03'
left join TRD_PRODUCT_DEAL C on B.TRADE_ID = C.P_TRADE_ID and C.TRADE_STATUS = '03' inner join TRD_TRADE_FEE_DETAIL D on D.TRADE_ID = B.TRADE_ID
and D.IS_PREPAID = 'Y' left join FIN_TRADE_PRODUCT E on E.FINPROD_ID = B.TRADE_ID and E.FINPROD_TYPE = 'C19' where C.TRADE_ID IS NULL and E.FINPROD_ID IS NULL and A.BOOKSET_ID = #{booksetId} and B.TRADE_ID = #{finprodId}
